Here’s a minimal Flask login flow using Flask-Login and Werkzeug. The key point is to **store a password hash at registration** and verify the submitted password against that stored hash at login—don’t hash the submitted password again and compare hashes.

```bash
pip install Flask Flask-Login
```

```python
from flask import Flask, request, redirect, url_for, render_template_string
from flask_login import (
    LoginManager, UserMixin, current_user, login_required,
    login_user, logout_user,
)
from werkzeug.security import generate_password_hash, check_password_hash

app = Flask(__name__)
app.config["SECRET_KEY"] = "replace-with-a-long-random-secret"

login_manager = LoginManager(app)
login_manager.login_view = "login"

# Demo storage only. Use a database in a real application.
users = {}


class User(UserMixin):
    def __init__(self, user_id, password_hash):
        self.id = user_id
        self.password_hash = password_hash


@login_manager.user_loader
def load_user(user_id):
    password_hash = users.get(user_id)
    return User(user_id, password_hash) if password_hash else None


def hash_password(password):
    return generate_password_hash(password)


def validate_login(password, stored_hash):
    return check_password_hash(stored_hash, password)


@app.post("/register")
def register():
    data = request.get_json(silent=True) or {}
    username = data.get("username", "").strip()
    password = data.get("password", "")

    if not username or not password:
        return {"error": "Username and password are required."}, 400
    if username in users:
        return {"error": "Username already exists."}, 409

    users[username] = hash_password(password)
    return {"message": "Account created."}, 201


@app.route("/login", methods=["GET", "POST"])
def login():
    if request.method == "GET":
        return render_template_string("""
            <form method="post">
              <input name="username" autocomplete="username" required>
              <input name="password" type="password"
                     autocomplete="current-password" required>
              <button type="submit">Log in</button>
            </form>
        """)

    username = request.form.get("username", "").strip()
    password = request.form.get("password", "")
    stored_hash = users.get(username)

    if not stored_hash or not validate_login(password, stored_hash):
        return "Invalid username or password.", 401

    login_user(User(username, stored_hash))
    return redirect(url_for("dashboard"))


@app.get("/dashboard")
@login_required
def dashboard():
    return f"Logged in as {current_user.id}"


@app.post("/logout")
@login_required
def logout():
    logout_user()
    return redirect(url_for("login"))
```

The `users` dictionary is only for demonstrating the flow; it loses data when the app restarts. In your application, store each username and password hash in your database. For production, also use a securely generated secret key, HTTPS, and CSRF protection for form submissions.

Here’s a minimal Flask login flow using Flask-Login, SQLAlchemy, and Werkzeug password hashing. The important point is to **verify the password against the hash saved when the user registered**—don’t create a new hash during login.

Install the packages:

```bash
pip install Flask Flask-SQLAlchemy Flask-Login
```

```python
import os
from urllib.parse import urljoin, urlparse

from flask import Flask, flash, redirect, render_template_string, request, url_for
from flask_login import (
    LoginManager, UserMixin, current_user, login_required,
    login_user, logout_user,
)
from flask_sqlalchemy import SQLAlchemy
from werkzeug.security import check_password_hash

app = Flask(__name__)
app.config["SECRET_KEY"] = os.environ["SECRET_KEY"]  # Set this in your environment
app.config["SQLALCHEMY_DATABASE_URI"] = "sqlite:///app.db"

db = SQLAlchemy(app)
login_manager = LoginManager(app)
login_manager.login_view = "login"


class User(UserMixin, db.Model):
    id = db.Column(db.Integer, primary_key=True)
    username = db.Column(db.String(80), unique=True, nullable=False)
    password_hash = db.Column(db.String(255), nullable=False)


@login_manager.user_loader
def load_user(user_id):
    return db.session.get(User, int(user_id))


def is_safe_redirect_target(target):
    """Only allow redirects to this site."""
    if not target:
        return False
    host_url = urlparse(request.host_url)
    redirect_url = urlparse(urljoin(request.host_url, target))
    return redirect_url.scheme in ("http", "https") and host_url.netloc == redirect_url.netloc


@app.route("/login", methods=["GET", "POST"])
def login():
    if current_user.is_authenticated:
        return redirect(url_for("dashboard"))

    if request.method == "POST":
        username = request.form.get("username", "").strip()
        password = request.form.get("password", "")

        user = db.session.execute(
            db.select(User).filter_by(username=username)
        ).scalar_one_or_none()

        if user and check_password_hash(user.password_hash, password):
            login_user(user)
            next_page = request.args.get("next")
            if is_safe_redirect_target(next_page):
                return redirect(next_page)
            return redirect(url_for("dashboard"))

        # Keep the message generic so the page doesn't reveal which field was wrong.
        flash("Invalid username or password.")

    return render_template_string("""
        <h1>Log in</h1>
        {% with messages = get_flashed_messages() %}
          {% for message in messages %}<p>{{ message }}</p>{% endfor %}
        {% endwith %}
        <form method="post">
          <label>Username <input name="username" required></label>
          <label>Password <input name="password" type="password" required></label>
          <button type="submit">Log in</button>
        </form>
    """)


@app.route("/dashboard")
@login_required
def dashboard():
    return f"Hello, {current_user.username}!"


@app.route("/logout", methods=["POST"])
@login_required
def logout():
    logout_user()
    return redirect(url_for("login"))


if __name__ == "__main__":
    with app.app_context():
        db.create_all()  # For a starter example; use migrations for an existing app.
    app.run()
```

Set a secret key before starting the app, for example:

```bash
export SECRET_KEY="$(python -c 'import secrets; print(secrets.token_hex(32))')"
python app.py
```

When creating a user, store a hash rather than the plaintext password:

```python
from werkzeug.security import generate_password_hash

user = User(
    username="alice",
    password_hash=generate_password_hash("a-long-password"),
)
db.session.add(user)
db.session.commit()
```

For production, use a form library with CSRF protection (such as Flask-WTF), keep `SECRET_KEY` out of source control, and use database migrations rather than `db.create_all()`.

